7	const [op,...args]=process.argv.slice(2);
8	if(op==='read'){
9	 const [purpose,...files]=args;
10	 for(const rel of files){const p=path.resolve(project,rel);if(!p.startsWith(path.resolve(project)+path.sep))throw Error('outside project');const b=fs.readFileSync(p),t=b.toString('utf8');console.log(JSON.stringify({path:rel,sha256:hash(b),bytes:b.length}));console.log(t);console.log('END FULL FILE '+rel);fs.appendFileSync(stage+'/reading.jsonl',JSON.stringify({at:new Date().toISOString(),path:rel,sha256:hash(b),purpose,range:'full',method:'full text emitted to model; hash scan alone not counted'})+'\n');}
11	}else if(op==='clock'){console.log(JSON.stringify({now:new Date().toISOString(),elapsed_s:(Date.now()-JSON.parse(fs.readFileSync(stage+'/start.json')).epoch_ms)/1000}));
12	}else if(op==='ledger'){const b=fs.readFileSync(project+'/.writer/state.json'),s=JSON.parse(b);console.log(JSON.stringify({sha256:hash(b),keys:Object.keys(s),snapshot_keys:Object.keys(s.snapshot),ledger_summary:Object.entries(s.snapshot.ledger??{}).map(([id,x])=>({id,type:x.type,status:x.status,due_unit:x.due_unit,statement:x.statement}))},null,2));
13	}else if(op==='items'){const s=JSON.parse(fs.readFileSync(project+'/.writer/state.json'));for(const id of args){const x=s.snapshot.ledger[id];if(!x)throw Error(id);console.log(JSON.stringify({id,...x},null,2));}
14	}else if(op==='recalls'){for(const id of args){const r=runner.run('node',['bin/ai-writer.mjs','recall','--project',project,'--query',id,'--limit','1'],'recall-'+id.toLowerCase());if(r.exit_code!==0)throw Error(r.stderr||r.stdout);const j=JSON.parse(r.stdout),m=j.matches.find(x=>x.id===id);if(!m)throw Error('exact ID missing '+id);console.log(JSON.stringify({id,entry:m.entry,files:r.files}));}
15	}else if(op==='ledger-current'){const b=fs.readFileSync(project+'/.writer/state.json'),s=JSON.parse(b);const rows=Object.entries(s.snapshot.ledger).filter(([id,x])=>x.status!=='resolved');const start=+args[0]||0,count=+args[1]||25;for(const [id,x]of rows.slice(start,start+count)){const {evidence,character_known,...rest}=x;console.log(JSON.stringify({id,...rest,character_known,evidence_count:evidence?.length,evidence_first:evidence?.[0],evidence_latest:evidence?.slice(-2)}));}console.log(JSON.stringify({total:rows.length,range:[start,Math.min(start+count,rows.length)],state_sha256:hash(b),scope:'all current fields; historical evidence first and last anchors only'}));
16	}else if(op==='save-template'){const n=+args[0],r=runner.json('template-'+n);fs.writeFileSync(stage+'/template-'+n+'-before.json',JSON.stringify(r,null,2)+'\n',{flag:'wx'});console.log(r);
17	}else if(op==='ledger-export'){const b=fs.readFileSync(project+'/.writer/state.json'),s=JSON.parse(b);const rows=Object.entries(s.snapshot.ledger).filter(([id,x])=>x.status!=='resolved');const data=rows.map(([id,x])=>{const {evidence,...rest}=x;return {id,...rest,evidence_count:evidence?.length,evidence_first:evidence?.[0],evidence_latest:evidence?.slice(-2)};});for(let i=0;i<data.length;i+=8)fs.writeFileSync(stage+'/ledger-current-'+i+'.json',JSON.stringify({state_sha256:hash(b),scope:'complete non-resolved current fields and character_known; historical evidence first/latest anchors; relevant full histories through recall',total:rows.length,entries:data.slice(i,i+8)},null,2)+'\n');console.log({files:data.length,parts:Math.ceil(data.length/8)});
18	}else if(op==='attest'){const [purpose,...files]=args;for(const rel of files){const b=fs.readFileSync(project+'/'+rel);fs.appendFileSync(stage+'/reading.jsonl',JSON.stringify({at:new Date().toISOString(),path:rel,sha256:hash(b),purpose,range:'full',method:'FastCtx full text read in preceding calls; hash recorded afterwards'})+'\n');}console.log({recorded:files.length});
19	}else if(op==='recovery-seal'){const rows=fs.readFileSync(stage+'/reading.jsonl','utf8').trim().split('\n').map(JSON.parse),u=[...new Map(rows.map(x=>[x.path,x])).values()];let t='\n## 已实读恢复源 SHA-256\n\n';for(const x of u)t+='- '+x.path+' `'+x.sha256+'`（全文）\n';for(let i=0;i<92;i+=8){const p=stage+'/ledger-current-'+i+'.json',b=fs.readFileSync(p);fs.appendFileSync(stage+'/reading.jsonl',JSON.stringify({at:new Date().toISOString(),path:p,sha256:hash(b),purpose:'nonresolved ledger complete current fields and knowledge; history anchors explicit',range:'full',method:'FastCtx full text read; state-derived current projection, not original-state full-read claim'})+'\n');t+='- ledger-current-'+i+'.json `'+hash(b)+'`（全文，现行字段与知识，历史证据仅首末锚）\n';}fs.appendFileSync(stage+'/recovery.md',t);fs.mkdirSync(stage+'/baseline',{recursive:true});fs.copyFileSync(project+'/.writer/state.json',stage+'/baseline/state-initial.json');console.log({sources:u.length,state_sha256:hash(fs.readFileSync(project+'/.writer/state.json')),recovery_sha256:hash(fs.readFileSync(stage+'/recovery.md'))});
20	}else if(op==='context-audit'){const j=runner.json('context-'+args[0]);console.log(JSON.stringify({keys:Object.keys(j),revision:j.revision,source_hashes:j.source_hashes,outline:j.outline,long_keys:Object.keys(j.long_form??{}),omitted:j.long_form?.recall?.omitted_ids??j.long_form?.omitted_ids??j.memory?.omitted_ids},null,2));
21	}else if(op==='metrics'){for(const n of args){const f=fs.readdirSync(project+'/正文').find(f=>f.startsWith(String(n).padStart(4,'0')+'-'));const b=fs.readFileSync(project+'/正文/'+f),t=b.toString('utf8').replace(/^#.*$/gm,'');console.log(JSON.stringify({unit:+n,file:f,han:(t.match(/\p{Script=Han}/gu)||[]).length,sha256:hash(b)}));}}
22	else throw Error('unknown operation');
